import type { Metadata } from 'next';
import { fetchPublicProfile } from '@/lib/publicProfile';
import { getTier } from '@/lib/tiers';
import ProfileClient from './ProfileClient';

type Props = { params: Promise<{ userId: string }> };

// Rendered on the server so link previews (iMessage, Discord, LinkedIn, X) see the
// name and score. The preview image itself is generated by opengraph-image.tsx.
export async function generateMetadata({ params }: Props): Promise<Metadata> {
  const { userId } = await params;
  const profile = await fetchPublicProfile(userId);
  if (!profile) return { title: 'Profile not found · JobDog' };

  const score = profile.topScore?.overallScore;
  const title = score !== undefined
    ? `${profile.displayName} scored ${score}/100 on JobDog`
    : `${profile.displayName} on JobDog`;
  const description = score !== undefined
    ? `${getTier(score).label} · ${profile.topScore?.summaryVerdict ?? 'Resume score'}. Get your own score on JobDog.`
    : 'Get your resume scored on JobDog.';
  return {
    title,
    description,
    openGraph: { title, description, type: 'profile' },
    twitter: { card: 'summary_large_image', title, description },
  };
}

export default async function PublicProfilePage({ params }: Props) {
  const { userId } = await params;
  const profile = await fetchPublicProfile(userId);
  return <ProfileClient profile={profile} />;
}
